// Top-down warship hull sprites from the "Sea Warfare Set" by Lowder2
// (opengameart.org/content/sea-warfare-set-ships-and-more), released CC0.
// Pixel art, drawn bow-up (axis 'v'); upscaled 5x (nearest-neighbour) and
// inlined as base64 so there are no runtime network requests and print stays crisp.

export interface ShipSprite {
  /** natural (pre-upscale) pixel dimensions, for aspect reference */
  w: number
  h: number
  uri: string
}

export const SHIP_SPRITE_ATTRIBUTION =
  'Ship sprites: "Sea Warfare Set" by Lowder2 (opengameart.org), CC0'

export const SHIP_SPRITES: Record<string, ShipSprite> = {  frigate: { w: 13, h: 55, uri: 'data:image/png;base64,' },
  submarine: { w: 35, h: 142, uri: 'data:image/png;base64,' },
  destroyer: { w: 20, h: 100, uri: 'data:image/png;base64,' },
  battleship: { w: 31, h: 209, uri: 'data:image/png;base64,' },
  carrier: { w: 57, h: 189, uri: 'data:image/png;base64,' },
}

